# -*- coding: utf-8 -*-
"""Обучение (аналоговый билд): учебный рейс по фиксированной карте. Возвращает HTML-блоки."""
from content import *

BY_ID = {e['id']: e for e in EVENTS}


def box(cls, title, body):
    return '<div class="%s"><b>%s</b> %s</div>' % (cls, title, body)


def say(text):
    return box('say', 'Писарь, читайте вслух:', text)


def teach(text):
    return box('teach', 'Объясните:', text)


def check(text):
    return box('ok', 'Контроль:', text)


def tutorial(event_block):
    h = []
    A = h.append
    A('<h1 class="pb">ОБУЧЕНИЕ</h1><h2>Первый рейс «Блюющего скелета»</h2>')
    A('<p>Учебная партия на <b>2–6 игроков</b>, 40–60 минут. Карта и порядок эпизодов <b>заранее известны</b>, чтобы по очереди пройти страницы буклета: Карта → Палуба → Порт → Борт. Броски настоящие; места, где обучение отличается от обычной игры, помечены «<b>в обучении</b>». Таймера в обучении нет.</p>')
    A('<table><tr><th>Урок</th><th>Страница буклета</th><th>Чему учит</th><th>Эпизод</th></tr>'
      '<tr><td>0</td><td>—</td><td>Подготовка, роли, шкалы</td><td>—</td></tr>'
      '<tr><td>1</td><td>Карта (стр. 4–5) — хаб игры</td><td>где мы и куда плывём, ход и разведка, значок клетки = эпизод, откуда игра отправляет на Палубу, Борт или в Порт</td><td>старт A4 → B4</td></tr>'
      '<tr><td>2</td><td>Палуба (стр. 2)</td><td>как ставить кубики на выбор: личные и общие слоты, обязательный (!) и тревожный (⚠), проверки, Раздача рома, рыбалка, метки</td><td>S2 «Бутылка с запиской»</td></tr>'
      '<tr><td>3</td><td>Порт (стр. 6–7)</td><td>Магазин (покупка, продажа, складчина), Игорный дом (крэпс, ставки, штучки), Поминки (Диковинки и Снаряжение → Искры), продажа рыбы</td><td>Порт (C3)</td></tr>'
      '<tr><td>4</td><td>Борт (стр. 3)</td><td>морской бой</td><td>учебный враг</td></tr>'
      '<tr><td>5</td><td>—</td><td>Искры и Воспоминания (флешбек)</td><td>—</td></tr>'
      '<tr><td>—</td><td>—</td><td>Конец обучения, дальше вас ждёт открытое море</td><td>—</td></tr></table>')

    # ------------------------------------------------------------- урок 0
    A('<h2>Урок 0. Подготовка</h2><ol>'
      '<li>Положите рядом: <b>Буклет</b>, <b>Буклет персонажей</b>, <b>Листы игры</b> (Корабельный журнал), эту книгу, карандаш с ластиком, кубики.</li>'
      '<li>Выберите скелетов (все разные) и впишите имена. При <b>2 игроках</b> каждый берёт двух скелетов, при <b>3 игроках</b> добавьте белый «скелет в маске» (кубик без листа). Каждому скелету свой кубик.</li>'
      '<li><b>Лист скелета</b> (буклет персонажей). <b>Навыки пусты</b>: стартовых навыков нет, клетки закрашиваются при прокачке. Клетки с ✕ справа — <b>потолок</b> вашего скелета (их не закрасить). ✦ на клетке даст Искру. <b>Слава, Удача, Сокровища</b> (без предела) и <b>Искры</b> у всех 0; метки <b>Благословение</b> и <b>Проклятие</b> пусты. Порядок выбора в обучении — по часовой стрелке от Писаря.</li>'
      '<li>В Корабельном журнале обведите стартовые значения: <b>Корпус 7 · Команда 6 · Ром 5 · Ропот 0</b>. Назовите корабль (по умолчанию «Блюющий скелет»). <b>Ропот</b> — недовольство команды: растёт от плохого, падает от хорошего; если <b>Ропот догнал Команду</b> (Ропот ≥ Команды), случается бунт мертвецов и вы проиграли.</li>'
      '<li><b>Писарь</b> — тот, кто держит книгу. Роль переходит по часовой стрелке в начале каждого раунда.</li>'
      '<li>Откройте буклет на <b>Карте</b> (страницы 4–5): с неё начнётся первый урок.</li></ol>')
    A(check('листы скелетов и Корабельный журнал готовы, буклет открыт на Карте.'))

    # ------------------------------------------------------------- урок 1 (Карта)
    A('<h2>Урок 1. Карта: главная страница игры</h2>')
    A(teach('<b>Карта</b> — «хаб» игры: основная страница буклета, с которой вы <b>отправляетесь</b> на остальные. Каждый раунд начинается и заканчивается здесь. Клетка, где находится корабль, решает, куда идти дальше: в <b>море</b> (штиль, шторм, туман, остров, встреча с кораблём) — на <b>Палубу</b>; в <b>бой</b> — на <b>Борт</b>; в <b>порт</b> — на страницы <b>Порт</b> (события и торговля на суше). Закончив раунд, вы возвращаетесь на Карту и двигаете корабль.'))
    A('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 170" width="330" style="display:block;margin:2mm auto"><defs><marker id="ah" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#222"/></marker></defs><g font-family="Segoe UI, Arial, sans-serif" font-size="13" text-anchor="middle" stroke="#222" stroke-width="2" fill="#fff"><rect x="115" y="5" width="90" height="34"/><rect x="5" y="68" width="90" height="34"/><rect x="115" y="68" width="90" height="34"/><rect x="225" y="68" width="90" height="34"/><rect x="115" y="130" width="90" height="34"/></g><g stroke="#222" stroke-width="2" fill="none" marker-end="url(#ah)"><path d="M115,22 H50 V66"/><path d="M160,39 V66"/><path d="M205,22 H270 V66"/><path d="M50,102 V147 H113"/><path d="M160,102 V128"/><path d="M270,102 V147 H207"/></g><g font-family="Segoe UI, Arial, sans-serif" font-size="14" text-anchor="middle" fill="#111"><text x="160" y="27">Карта</text><text x="50" y="90">Палуба</text><text x="160" y="90">Порт</text><text x="270" y="90">Борт</text><text x="160" y="152">Карта</text></g></svg>')
    A(teach('Когда корабль вошёл в клетку и тип местности известен, <b>Писарь нажимает этот тип в приложении</b>: оно выбирает событие из случайного пула и подсказывает страницу, куда идти. <i>В прототипе приложения нет: типы местности и эпизоды берём из Книги событий (d6).</i> Если это <b>остров</b>, приложение даёт ему <b>номер</b>: впишите его <b>цифрой внутрь треугольника</b> △ на карте (△ с цифрой 1, 2, 3…). Остров может быть портом или необитаемым островом (его исследуют выборами на Палубе). Вернувшись на остров, Писарь вводит его номер, и вы попадаете на <b>тот же</b> порт или остров.'))
    A('<ol><li><b>Где мы и куда плывём.</b> Корабль стоит в <b>A4</b> (старт). В обучении нам нужно приплыть в порт <b>C3</b>. Нарисуйте там (в C3) треугольник △ и впишите <b>внутрь цифру 1</b> (остров №1 — порт «Тихий причал»): в обучении мы уже знаем, что это порт. Корабль на карту <b>не ставят</b>: ход рисуется <b>линией</b> из клетки в клетку, корабль находится там, где заканчивается последняя линия.</li>'
      '<li><b>Два способа действовать на карте.</b> <b>Ход</b> — проведите линию в соседнюю клетку (клетка-<b>сосед</b> касается стороны вашей, у каждой клетки 6 соседей). Ход <b>бесплатный</b>. <b>Разведка</b> — узнать, что в клетке, прежде чем туда плыть, и она <b>платная</b>: <b>Ром −1</b>.</li>'
      '<li><b>Как разведывать.</b> Игроки <b>сначала выбирают до 2 пустых клеток вокруг корабля</b>, затем бросают d6 на значок первой клетки, затем d6 на значок второй и <b>зарисовывают на карте выпавшее</b> (таблица значков — подсказка справа от карты).</li>'
      '<li><b>Разведаем.</b> Заплатите Ром −1 (в Корабельном журнале Ром 5 → 4) и выберите две клетки рядом с кораблём: <b>B4</b> и <b>B3</b>. <i>В обучении результат задан вместо броска: B4 — ~ (штиль), B3 — △ (остров). В обычной игре бросьте d6 на каждую клетку.</i> Остров рядом пригодится позже: при первом заходе ему дадут номер, а сейчас нам в штиль.</li>'
      '<li><b>Ещё одна трата Рома:</b> <b>полный вперёд</b> — Ром −1, корабль уходит на 2 клетки вместо 1. В обучении не используем.</li>'
      '<li><b>Теперь движемся.</b> Проведите линию <b>A4 → B4</b>. Корабль в B4. Значок клетки (~ штиль) говорит, какой тип эпизода играть: <b>штиль</b> → Палуба. Эпизод определяется значком <b>при каждом заходе</b> (и при повторном тоже): для каждого типа местности есть пул эпизодов.</li>'
      '<li>Если на клетке нет значка, Писарь бросает d6 по той же таблице и рисует его. Дальше — <b>Урок 2: Палуба</b>.</li></ol>')
    A(check('на карте нарисованы в C3 треугольник с цифрой 1, ~ в B4 и пустой треугольник △ в B3, проведена линия A4 → B4, корабль в B4; Ром 4.'))

    # ------------------------------------------------------------- урок 2 (Палуба)
    A('<h2>Урок 2. Палуба: как ставить кубики на выбор</h2>')
    A(teach('<b>Палуба</b> (страница 2) — страница, где игроки выбирают действия. <b>Слоты 1–3</b> (круги) <b>личные</b>: один кубик. <b>Слоты 4–6</b> (пунктир) <b>общие</b>: любое число кубиков. <b>Слот 7</b> — <b>рыбалка</b>, доступна только в штиль. Номер слота — порядок выполнения. Особые слоты: <b>обязательный («!»)</b>, всегда личный, на слоте 1 или 2 — кто-то из игроков <b>обязан</b> туда встать; <b>тревожный (⚠)</b> — вставать необязательно, но если в конце фазы действий на нём нет ни одного кубика, наступает штраф. Эпизод бывает <b>проходным</b> (один раунд, потом корабль уходит сам) или <b>циклом</b> (круг повторяется, пока кто-то не уведёт корабль слотом «Штурвал»; новый круг стоит Ропот +1). Этот эпизод проходной.'))
    A('<ol><li><b>Эпизод.</b> Карта отправила вас сюда: значок B4 — штиль. Откройте <b>Палубу</b> (страница 2, справа Борт). Писарь читает вслух блок «Читать вслух» ниже (название, описание, предупреждение).</li>'
      '<li><b>Слоты.</b> Объявите: <b>слот 1 — не Штурвал</b> (в проходном эпизоде корабль уходит сам); в нём стоит <b>обязательное действие (!)</b> «Раздача рома»; <b>слот 4 — тревожный (⚠)</b> «Договориться с джинном»; <b>слот 7</b> — рыбалка (сейчас штиль). Отметьте ! и ⚠ карандашом на номерах слотов.</li>'
      '<li><b>Планирование.</b> По очереди каждый ставит свой кубик на один слот. <b>Это как поставить фигурку-маркер: кубик здесь не бросают.</b> Личный слот — один кубик, общий — сколько угодно. Обсуждать можно. Результаты не читайте. Рядом с названием стоят <b>иконка навыка</b> (если будет проверка) и иконки параметров, которых коснётся действие, но не сказано, прибавится оно или убавится.</li>'
      '<li><b>Действия по номерам 1 → 7.</b> Если действие — <b>проверка</b>, игрок сначала <b>получает +1 к навыку</b> этой проверки (закрашивает клетку на листе скелета; клетка с ✦ даёт Искру; клетку с ✕ закрасить нельзя), затем бросает свой кубик, прибавляет уровень навыка и называет сумму; Писарь читает исход. Если выпало мало, можно потратить <b>Удачу</b>: 1 Удача = 1 переброс (Удачу дают некоторые исходы, например «Выбить пробку кулаком»). Если проверки нет, исход читается сразу.</li>'
      '<li><b>Раздача рома (обязательное действие).</b> Тот, кто встал на слот 1, выбирает: <b>налить всем</b> (Ром −Жажда, Ропот −1), <b>зажать</b> (Ропот +1) или <b>пустить к бочке</b> (Ром −(Жажда+2), себе Слава +2). <b>Жажда</b> зависит от Команды: 1–3 → 1, 4–7 → 2, 8–10 → 3 (сейчас Команда 6, Жажда 2).</li>'
      '<li><b>Рыбалка (слот 7).</b> Игрок проводит проверку Мормышки: ≤3 — ничего, 4–6 — <b>один</b> бросок d6 по таблице улова на Палубе (столбец «Штиль», строки 1–2, 3–4, 5–6), 7–9 — <b>два</b> броска, выберите один улов, 10+ — два броска, берите оба. Закрасьте квадратик у пойманной рыбы: она <b>на корабле</b>. Рыба — товар: её продают за монеты в порту (других эффектов у неё нет).</li>'
      '<li><b>Метки.</b> Если исход велел получить <b>Благословение</b> (например, джинн на провале) или <b>Проклятие</b>, поставьте ✓ на метке в листе скелета. Метка <b>обязательна</b> для вашей следующей проверки: Благословение — два кубика, берёте <b>худший</b>, Проклятие — два кубика, берёте <b>лучший</b>; потом метку снимите. Обе метки: снимите обе, бросьте один кубик.</li>'
      '<li><b>Тревожный слот.</b> Если в конце фазы действий на слоте 4 нет кубиков, будет штраф. <i>Для наглядности один раз не ставьте туда кубик и посмотрите штраф в разделе.</i></li>'
      '<li><b>Конец раунда.</b> Сам по себе Ром не убывает: его тратят Раздача и события. Если Ром = 0, Ропот +1 («трезвая тоска»). Если Ропот догнал Команду — бунт мертвецов, вы проиграли. Уберите кубики и отметки. Затем корабль уходит (см. ниже).</li></ol>')
    A(event_block(BY_ID['S2']))
    A(teach('<b>Корабль уходит.</b> Проходной эпизод закончился, и корабль <b>уходит из клетки сам, что бы ни случилось</b>. Вы <b>возвращаетесь на Карту</b>, и группа проводит линию <b>B4 → C3</b>: там порт назначения. <i>В обучении маршрут короткий, поэтому разведывать больше нечего.</i>'))
    A(check('линия B4 → C3 проведена, корабль в C3; Ром 4 (зажали), 2 (налили) или 0 (пустили к бочке: тогда трезвая тоска, Ропот +1); у кого-то закрашены клетки навыков, есть рыба или метка.'))

    # ------------------------------------------------------------- урок 3 (Порт)
    A('<h2>Урок 3. Порт: Магазин, Игорный дом и Поминки</h2>')
    A(teach('<b>Порт</b> — страницы 6–7 буклета. Слева <b>слоты 1–4</b> (1–3 личные, 4 общий: в Рыночном порту это <b>Поминки</b>), под ними <b>Игорный дом</b> (ячейка 6, общая) и колонка «Шуллерские штучки». Справа <b>Магазин</b> (ячейка 5, общая). Раунд в порту идёт по обычным правилам: планирование, действия, конец раунда. В порту Ром не убывает: тут пьют за свои.'))
    A('<ol><li><b>Карта → Порт.</b> Корабль в C3, остров №1 — порт назначения. Бросьте d6 на <b>тип порта</b> (в обучении: Рыночный порт: есть и Магазин, и Игорный дом). <i>В обучении каждый скелет получает «жалованье»: <b>Сокровища +3</b> и одну Диковинку «Ракушка» (впишите в «Предметы»).</i></li>'
      '<li>Откройте разворот <b>Порт</b>. Писарь читает блок порта ниже (слоты 1–4).</li>'
      '<li><b>Планирование.</b> Игроки ставят кубики на слоты: порт (1–4), Магазин (5) и/или Игорный дом (6). Попросите <b>хотя бы одного</b> игрока в Магазин, <b>одного</b> в Игорный дом и <b>одного</b> на Поминки (слот 4).</li></ol>')
    A(teach('<b>Магазин (слот 5).</b><ol>'
            '<li>Столбец <b>«Всегда в наличии»</b> (Курочка, Зеваки, Ремонт, Песенник, Бочка рома, Большой ремонт) доступен целиком и без ограничений.</li>'
            '<li>Для столбцов <b>«Снаряжение», «Диковинки», «Бой», «Услуги»</b> бросьте d6 на каждый: выпавший номер — товар в наличии, <b>одна штука</b>.</li>'
            '<li><b>Купить.</b> Игрок на слоте 5 платит <b>Сокровищами</b> (число в монете у товара) и получает товар. Эффект («Ром +1», «Корпус +1», «Ропот −2» и т. д.) применяется сразу; <b>Снаряжение</b> и <b>Диковинку</b> впишите в «Предметы» листа скелета. Покупать можно сколько угодно, пока хватает монет. <i>Курочка и Ремонт по 1 монете: можно брать много; Бочка рома и Большой ремонт по 3 монеты: «опт» (четыре штуки по цене трёх).</i></li>'
            '<li><b>Продать.</b> Половина цены, вниз, не меньше 1: можно продавать Снаряжение и Диковинки. Рыбу продают отдельно по ценам таблицы улова (в каждом порту свои условия: см. описание порта; Рыночный платит по цене), слот для этого не нужен.</li>'
            '<li><b>Складчина.</b> Игроки свободно передают друг другу монеты и предметы (пока корабль на карте): можно отправить в Магазин одного игрока с деньгами всей команды. <i>В обучении скиньтесь и купите Снаряжение (4 монеты).</i></li>'
            '<li><b>Снаряжение</b> даёт купившему <b>+2</b> к проверкам навыка (иконка навыка у предмета), <b>Диковинка</b> — разовый эффект (зачеркните после использования) <b>или</b> сжечь её на Поминках.</li></ol>'))
    A(teach('<b>Игорный дом (слот 6).</b><ol>'
            '<li>Все, кто поставил кубик на слот 6, играют вместе в <b>крэпс</b> на Сокровища. Каждый ставит на любые <b>ставки №1–№5</b> (список у слота): <b>не больше 2 монет на ставку, на №4 и №5 не больше 1</b>. Запишите карандашом, кто сколько куда поставил.</li>'
            '<li>Желающие покупают <b>Шуллерские штучки</b> (колонка слева внизу, цены по возрастанию): до броска, поставьте ✓; использованную потом зачеркните.</li>'
            '<li><b>Бросок:</b> 2d6 (свой кубик и ещё любой: в коробке 6 кубиков). <b>Первый бросок</b>: 7 или 11 — победа, 2, 3 или 12 — проигрыш, любое другое число — <b>Цель</b>. Если выпала Цель, бросайте снова: Цель — победа, 7 — проигрыш.</li>'
            '<li><b>Выигрыш.</b> Выигравшая ставка возвращается с прибылью: №1 — 1:1, №2 — 2:1, №3 — 4:1, №4 — 10:1, №5 — 15:1. Проигравшая ставка сгорает.</li></ol>'))
    A(teach('<b>Поминки (слот 4).</b><ol>'
            '<li>Поставьте кубик на слот 4 (общий): здесь вспоминают ушедших и сжигают вещи на алтаре предков.</li>'
            '<li>Положите на алтарь <b>до 2 приношений</b>: <b>1 Диковинку</b> (Искры написаны в слоте: Ракушка, Шкатулка, Зуб кита — 1, Склянка, Часы — 2, Бутыль — 3) <b>или 2 Снаряжения</b> (1 Искра). Рыбу и Шуллерские штучки нельзя.</li>'
            '<li>Зачеркните приношения в «Предметах» и <b>обведите в строке «Искры» столько кружков</b>, сколько получили (всего не больше 5).</li>'
            '<li>Искры нужны для Воспоминаний (урок 5) и личной концовки скелета. <i>В обучении сожгите свою Ракушку: получите 1 Искру.</i></li></ol>'))
    A('<ol><li><b>Раунд 1.</b> Разыграйте слоты по номерам 1 → 6, как на Палубе. Конец раунда как обычно.</li>'
      '<li><b>Раунд 2.</b> Повторите, чтобы попробовали остальные слоты.</li></ol>')
    A(event_block(PORTS[0], 'port'))
    A(teach('<b>Выход из порта.</b> Закончив порт, вернитесь на Карту и проведите линию из C3 в соседнюю клетку (в обучении — в B3). Корабль выходит в море.'))
    A(check('Монеты изменились у каждого (покупки, ставки, продажа рыбы); у кого-то сожжена Ракушка и обведена Искра.'))

    # ------------------------------------------------------------- урок 6
    A('<h2>Урок 4. Борт (морской бой)</h2>')
    A(teach('<b>Борт</b> (стр. 3, справа от Палубы) — планшет вашего корабля. Книжку при бое поворачивают набок: текст читается с края. Бой идёт <b>кругами</b>: каждый скелет ходит <b>один раз</b>. За круг становится ясно: победа, поражение или ничья. Ходящий всегда бросает <b>5 кубиков</b>, как в Yahtzee.'))
    A('<ol><li>Корабль выходит из порта. Появляется учебный враг: <b>«Чайка-налётчица»</b> (слабый класс). Писарь читает: «В небе кружит тень. Это огромная чайка с пушкой. Она очень хочет ваш обед».</li>'
      '<li>Запишите врага в поля планшета по числу скелетов: <b>4 → Корпус 12, Руль 10; 5 → Корпус 14, Руль 8; 6 → Корпус 17, Руль 6</b>; урон врага <b>1</b>. Если у кого-то куплена «Смазка» или «Парусина», впишите в полосу «Улучшения корабля на бой» внизу Борта.</li>'
      '<li><b>Кубики.</b> В коробке 6 кубиков: в бою берите любые 5.</li>'
      '<li><b>Ход скелета.</b> Первым ходит игрок с наибольшей Славой. Он <b>бросает 5 кубиков</b>, <b>один раз</b> может перебросить любое число из них (Удача даёт ещё переброс), затем <b>раскладывает кубики по станциям</b>: каждый кубик на одну станцию или откладывает.</li>'
      '<li><b>Станции.</b> <b>Пушки</b> — пара и больше одинаковых (2→1, 3→3, 4→5, 5→8 урона); <b>Таран</b> — стрит от 3 подряд (3→2, 4→4, 5→6); <b>Руль</b> — сумма на станции ≥ S: залп врага мимо; <b>Трюм</b> — каждый кубик 1–2: Корпус +1. Навык станции ≥3 у ходящего даёт +1 к эффекту.</li>'
      '<li><b>Враг стреляет после каждого хода:</b> если Руль не сработал, Корпус −1. Поэтому стоит класть кубики и на Руль.</li>'
      '<li>Ходит следующий скелет. Слава +1 тому, кто нанёс 3 урона и больше.</li>'
      '<li><b>Исход круга.</b> Корпус врага 0 — победа (награда: Сокровища +3 каждому). Враг цел и корабль цел — <b>ничья</b>: враг улетает, награда половинная (Сокровища +1). Корпус корабля 0 — поражение. Использованные улучшения отметьте ✗.</li></ol>')
    A(check('исход боя ясен за один круг (по одному ходу каждого скелета); Корпус врага и корабля записаны.'))

    # ------------------------------------------------------------- урок 7
    A('<h2>Урок 5. Воспоминания</h2>')
    A(teach('Клетка навыка закрашивается как обычно; если в ней ✦, вы получаете ещё и <b>Искру</b> (обведите кружок в строке «Искры»). Периодически (в свободном плавании после каждого третьего эпизода) наступает событие <b>«Воспоминания»</b>: каждый скелет с непережитой Искрой переживает флешбек из своей жизни и делает выбор.'))
    A('<ol><li><i>В обучении</i> каждый скелет получает 1 Искру (обведите кружок).</li>'
      '<li>По очереди каждый игрок рассказывает флешбек своего скелета в 1–2 предложениях (как он умер, чего не закончил).</li>'
      '<li>Каждый выбирает: <b>Гордость</b> (Ропот −1 кораблю) или <b>Стыд</b> (Слава +1 ему).</li>'
      '<li>Зачеркните Искру: она пережита. Когда пережиты все пять, скелет упокоился.</li></ol>')

    A('<h2>Конец обучения, дальше вас ждёт открытое море</h2>')
    A('<ol><li>Обсудите, что было непонятно (запишите в Лист теста).</li>'
      '<li>Сотрите карту и Судовой журнал. Обнулите Корабельный журнал, листы скелетов (Слава, Удача, Сокровища, Искры, Снаряжение).</li>'
      '<li>Перейдите к «Свободное плавание: подготовка» дальше в этой книге.</li></ol>')
    A('<h3>Итог обучения: что вы должны были увидеть</h3><table>'
      '<tr><td>Карта</td><td>хаб игры; ход бесплатный, разведка за ром; значки клеток; номера островов</td></tr>'
      '<tr><td>Палуба</td><td>личные и общие слоты; обязательный (!) и тревожный (⚠) слоты; проверка d6 + навык; Удача; Раздача рома; метки; рыбалка</td></tr>'
      '<tr><td>Порт</td><td>Магазин, складчина, Игорный дом (крэпс), Поминки, продажа рыбы</td></tr>'
      '<tr><td>Борт</td><td>станции, комбинации кубиков, улучшения на бой</td></tr></table>')
    return h
